package core
import("testing";"strings";"encoding/json";"everything-go/internal/messagequeue")
func TestQAFoundationSealCannotDropReservedAssets(t *testing.T){h,c,s,b:=humanCoreFixture(t);release:=s.HoldQueue();defer func(){s.Close();release()}();h.cfg.InstanceID="authority";b.Authority=h.cfg.InstanceID;r:=messagequeue.HumanOperation{ID:"reserve-assets",Kind:"reserve",Request:"r_assets",Content:"whole body",IntentHash:strings.Repeat("a",64),Assets:json.RawMessage(`[{"id":"original-image","kind":"image","sha256":"`+strings.Repeat("b",64)+`"}]`)};h.handleHumanInput(c,humanCoreCommand(b,r));_ = waitForType(t,c,"queue_input_result");seal:=messagequeue.HumanOperation{ID:"seal-without-assets",Kind:"seal",Request:r.Request,ExpectedRevision:1,ContentRevision:1,IntentHash:r.IntentHash,Content:r.Content,ReadyProof:r.IntentHash};h.handleHumanInput(c,humanCoreCommand(b,seal));_ = waitForType(t,c,"queue_input_result");if e,ok,err:=h.messageQueue.Get(s.ID,r.Request);err!=nil{t.Fatal(err)}else if ok{t.Fatalf("reserved image omitted but final Entry accepted: images=%d files=%v",e.ImageCount,e.FileNames)}}
